/*
 * Release signing — the keystore NEVER lives in the repository.
 * Locally: export the 4 variables in your shell. In CI: they come from GitHub secrets
 * (see .github/workflows/release.yml). If any is missing, the release build is produced
 * UNSIGNED instead of failing, so `assembleRelease` still works on any machine.
 */
val keystorePath: String? = System.getenv("POCKETMIND_KEYSTORE_PATH")
val keystorePassword: String? = System.getenv("POCKETMIND_KEYSTORE_PASSWORD")
val signingKeyAlias: String? = System.getenv("POCKETMIND_KEY_ALIAS")
val signingKeyPassword: String? = System.getenv("POCKETMIND_KEY_PASSWORD")
val hasReleaseKeystore = listOf(keystorePath, keystorePassword, signingKeyAlias, signingKeyPassword)
    .all { !it.isNullOrBlank() } &&
    file(keystorePath!!).exists()

/*
 * Version from the release tag (see AppVersion in build-logic): CI passes the tag it builds in
 * POCKETMIND_VERSION_TAG; locally the newest "v*" tag reachable from HEAD is used; without any
 * tag the build is "0.0.0-dev" (versionCode 1). Nobody edits version numbers by hand.
 */
val versionTag: String? = providers.environmentVariable("POCKETMIND_VERSION_TAG").orNull
    ?: providers.of(GitTagValueSource::class.java) { }.orNull
val appVersion = AppVersion.fromTag(versionTag)

android {
    namespace = "com.sanjay.pocketmind"

    defaultConfig {
        applicationId = "com.sanjay.pocketmind"
        versionCode = appVersion.code
        versionName = appVersion.name
    }

    packaging {
        resources {
            // Post-quantum crypto tables from Bouncy Castle (pulled in by PdfBox for encrypted
            // PDFs). PdfBox never uses these algorithms; they were 4.0 MB of the APK (AUDIT M-1).
            excludes += "org/bouncycastle/pqc/**"
        }
    }

    buildFeatures {
        // BuildConfig.DEBUG decides whether Timber logs anything.
        buildConfig = true
    }

    signingConfigs {
        if (hasReleaseKeystore) {
            create("release") {
                storeFile = file(keystorePath!!)
                storePassword = keystorePassword
                keyAlias = signingKeyAlias
                keyPassword = signingKeyPassword
            }
        }
    }

    buildTypes {
        release {
            // R8 shrinks, optimizes and obfuscates the code; shrinkResources removes unused
            // images/strings. Together they make the APK much smaller.
            isMinifyEnabled = true
            isShrinkResources = true
            proguardFiles(getDefaultProguardFile("proguard-android-optimize.txt"), "proguard-rules.pro")
            if (hasReleaseKeystore) signingConfig = signingConfigs.getByName("release")
        }
    }
}

